sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var name = current.name;
    var num = current.sinsei_number;

    var gr = new GlideRecord('x_1882833_organi_0_meisai');
    gr.addQuery('name', name);
    gr.addQuery('sinsei_number', num);
    gr.query();

    var count = gr.getRowCount();
	gs.addInfoMessage(count);
    if (count == 0) {
        gs.addInfoMessage('test');
        var sho = new GlideRecord('x_1882833_organi_0_shozoku');
        sho.addQuery('user_id', current.name);
        sho.addQuery('kenmu_number', '!=', 1);
        sho.orderBy('kenmu_number');
        sho.query();

        while (sho.next()) {
            gs.addInfoMessage('test');
            // gr.initialize();
            // gr.sinsei_number = num;
            // gr.name = name;
            // gr.insert();
        }
    }



})(current, previous);
